          if (!grant) {
            NotificationUtil.Permission.openSettings();
          }
        })
      })
      Button("预设默认配置").onClick(async()=>{
        const smallIcon = await NotificationUtil.Tools.createCompressedIcon($r("app.media.notify_test_1"));
